:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e0e0e0;
  --accent: #0f3460;
  --highlight: #e94560;
  --key-bg: #1f4068;
  --key-hover: #2a5a8a;
  --key-active: #e94560;
  --success: #4ecca3;
  --error: #e94560;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 360px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: var(--highlight);
  letter-spacing: 2px;
}

.display {
  background: var(--bg);
  border-radius: 8px;
  padding: 16px;
  font-size: 1.5rem;
  letter-spacing: 8px;
  min-height: 56px;
  margin-bottom: 8px;
  font-family: monospace;
  color: var(--success);
  word-break: break-all;
}

.status {
  min-height: 24px;
  font-size: 1rem;
  margin-bottom: 16px;
  font-weight: bold;
}

.status.error {
  color: var(--error);
}

.status.success {
  color: var(--success);
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.key {
  background: var(--key-bg);
  color: var(--text);
  border: none;
  border-radius: 8px;
  padding: 16px 8px;
  font-size: 1.25rem;
  font-weight: bold;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  font-family: inherit;
}

.key:hover {
  background: var(--key-hover);
}

.key:focus-visible {
  outline: 3px solid var(--highlight);
  outline-offset: 2px;
}

.key:active {
  background: var(--key-active);
  transform: scale(0.95);
}

.key:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  transform: none;
}

.key--clear {
  background: var(--accent);
}

.key--clear:hover {
  background: var(--key-hover);
}

.key--enter {
  background: var(--highlight);
}

.key--enter:hover {
  background: #ff5a7a;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  .key {
    padding: 12px 4px;
    font-size: 1.1rem;
  }
  .display {
    font-size: 1.25rem;
    letter-spacing: 4px;
  }
}

const CORRECT_CODE = '4271';
const MAX_ATTEMPTS = 3;
const LOCKOUT_SECONDS = 10;

const displayEl = document.getElementById('display');
const statusEl = document.getElementById('status');
const keys = document.querySelectorAll('.key');

let entered = '';
let wrongAttempts = 0;
let locked = false;
let lockTimer = null;

function updateDisplay() {
  displayEl.textContent = entered || 'Enter code';
}

function setStatus(msg, type) {
  statusEl.textContent = msg;
  statusEl.className = 'status' + (type ? ' ' + type : '');
}

function setDisabled(disabled) {
  keys.forEach(k => k.disabled = disabled);
}

function lockKeypad() {
  locked = true;
  setDisabled(true);
  let remaining = LOCKOUT_SECONDS;
  setStatus('Locked for ' + remaining + 's', 'error');
  lockTimer = setInterval(() => {
    remaining--;
    if (remaining <= 0) {
      clearInterval(lockTimer);
      lockTimer = null;
      locked = false;
      wrongAttempts = 0;
      setDisabled(false);
      setStatus('Ready');
    } else {
      setStatus('Locked for ' + remaining + 's', 'error');
    }
  }, 1000);
}

function handleKey(key) {
  if (locked) return;
  if (key === 'clear') {
    entered = '';
    updateDisplay();
    setStatus('');
    return;
  }
  if (key === 'enter') {
    if (entered.length === 0) {
      setStatus('Enter a code', 'error');
      return;
    }
    if (entered === CORRECT_CODE) {
      setStatus('Unlocked', 'success');
      entered = '';
      updateDisplay();
      wrongAttempts = 0;
    } else {
      wrongAttempts++;
      setStatus('Wrong code', 'error');
      entered = '';
      updateDisplay();
      if (wrongAttempts >= MAX_ATTEMPTS) {
        lockKeypad();
      }
    }
    return;
  }
  if (entered.length < 4) {
    entered += key;
    updateDisplay();
    setStatus('');
  }
}

keys.forEach(btn => {
  btn.addEventListener('click', () => handleKey(btn.dataset.key));
});

document.addEventListener('keydown', (e) => {
  if (locked) return;
  const key = e.key;
  if (key >= '0' && key <= '9') {
    handleKey(key);
  } else if (key === 'Enter') {
    handleKey('enter');
  } else if (key === 'Escape' || key === 'Delete' || key === 'Backspace') {
    handleKey('clear');
  }
});

updateDisplay();
setStatus('Ready');
